import resultsText from '../../../../bench/results.json?raw';
import { formatBytes, h } from '../dom';

/** The shapes in bench/results.json (generated by bench/twins; see bench/TWINS.md and SPEC section 12). */
interface Checkpoint { everySteps: number; bytes: number; snapshots: number; meanReplaySteps: number; worstReplaySteps: number }
interface PongResult {
  frames: number;
  reversibleStepsPerFrame: number;
  conventionalStepsPerFrame: number;
  naiveDiaryBytes: number;
  tightDiaryBytes: number;
  reversibleGarbageBytes: number;
  reversibleMachineHistoryBytes: number;
  totalReversibleSteps: number;
  totalConventionalSteps: number;
  checkpoints: Checkpoint[];
  seekMeanSteps: { naiveDiary: number; tightDiary: number; reversible: number };
}
interface SortResult {
  reversibleSteps: number;
  conventionalSteps: number;
  garbageFlagsSet: number;
  garbageFlagsPossible: number;
  naiveDiaryBytes: number;
  tightDiaryBytes: number;
  reversibleMachineHistoryBytes: number;
}
export interface BenchResults { pong: PongResult; sort: SortResult }

export type Strategy = 'naive' | 'tight' | 'checkpoint' | 'reversible';

/** One strategy at one setting: what it holds after the run, and what it costs to go back. */
export interface BenchPoint {
  strategy: Strategy;
  name: string;
  /** Memory held after the whole run, in bytes. */
  bytes: number;
  /** Steps to seek to an arbitrary earlier time (mean), or null when the benchmark did not measure it. */
  seekMean: number | null;
  /** Steps to go back one step. */
  back1: string;
}

export const results: BenchResults = JSON.parse(resultsText);

const n0 = (v: number): string => Math.round(v).toLocaleString('en-GB');

/** The rows of the Pong table: the naive and the tight diary, three checkpoint intervals, and the reversible program. */
export function pongPoints(r: PongResult = results.pong): BenchPoint[] {
  return [
    { strategy: 'naive', name: 'Naive diary', bytes: r.naiveDiaryBytes, seekMean: r.seekMeanSteps.naiveDiary, back1: '1 undo step' },
    { strategy: 'tight', name: 'Tight diary', bytes: r.tightDiaryBytes, seekMean: r.seekMeanSteps.tightDiary, back1: '1 undo step' },
    ...r.checkpoints.map((c): BenchPoint => ({
      strategy: 'checkpoint',
      name: `Checkpoint, every ${n0(c.everySteps)} steps`,
      bytes: c.bytes,
      seekMean: c.meanReplaySteps,
      back1: `up to ${n0(c.worstReplaySteps)} steps of replay`,
    })),
    { strategy: 'reversible', name: 'Reversible', bytes: r.reversibleGarbageBytes + r.reversibleMachineHistoryBytes, seekMean: r.seekMeanSteps.reversible, back1: '1 inverse step' },
  ];
}

const NS = 'http://www.w3.org/2000/svg';
function svgEl<K extends keyof SVGElementTagNameMap>(tag: K, attrs: Record<string, string | number> = {}, text?: string): SVGElementTagNameMap[K] {
  const e = document.createElementNS(NS, tag);
  for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, String(v));
  if (text !== undefined) e.textContent = text;
  return e;
}

const COLOUR: Record<Strategy, string> = { naive: '#8fa8ff', tight: '#5fd0c2', checkpoint: '#c9d1d9', reversible: '#3fb950' };

/** Where each label sits next to its point (dx, dy, anchor), so the labels do not collide. */
const LABEL: Record<string, [number, number, 'start' | 'end']> = {
  naive: [-10, 18, 'end'], tight: [10, -10, 'start'], reversible: [-12, 5, 'end'],
};

/** Memory held (log scale) against steps to seek to an arbitrary earlier time (log scale), one labelled point per strategy. */
export function benchChart(points: readonly BenchPoint[]): SVGSVGElement {
  const W = 680, H = 330, L = 92, R = 24, T = 16, B = 52;
  const svg = svgEl('svg', { viewBox: `0 0 ${W} ${H}`, class: 'cmp-chart-svg', role: 'img' });
  const plotted = points.filter((p): p is BenchPoint & { seekMean: number } => p.seekMean !== null);
  svg.setAttribute('aria-label', `Memory held against steps to seek, both on log scales. ${plotted.map((p) => `${p.name}: ${formatBytes(p.bytes)}, ${n0(p.seekMean)} steps`).join('. ')}.`);
  const xLo = 10, xHi = 100_000, yLo = 1024, yHi = 10 * 1024 * 1024;
  const lx = (v: number): number => L + ((Math.log10(Math.max(v, xLo)) - Math.log10(xLo)) / (Math.log10(xHi) - Math.log10(xLo))) * (W - L - R);
  const ly = (v: number): number => H - B - ((Math.log10(Math.max(v, yLo)) - Math.log10(yLo)) / (Math.log10(yHi) - Math.log10(yLo))) * (H - T - B);

  const ticks: [number, string][] = [[1024, '1 KiB'], [10 * 1024, '10 KiB'], [100 * 1024, '100 KiB'], [1024 * 1024, '1 MiB'], [10 * 1024 * 1024, '10 MiB']];
  for (const [v, text] of ticks) {
    svg.append(svgEl('line', { x1: L, x2: W - R, y1: ly(v), y2: ly(v), class: 'cmp-grid' }), svgEl('text', { x: L - 8, y: ly(v) + 4, class: 'cmp-tick', 'text-anchor': 'end' }, text));
  }
  for (let e = 1; e <= 5; e++) {
    const v = 10 ** e;
    svg.append(svgEl('line', { x1: lx(v), x2: lx(v), y1: T, y2: H - B, class: 'cmp-grid' }), svgEl('text', { x: lx(v), y: H - B + 18, class: 'cmp-tick', 'text-anchor': 'middle' }, n0(v)));
  }
  svg.append(
    svgEl('text', { x: (L + W - R) / 2, y: H - 8, class: 'cmp-axis', 'text-anchor': 'middle' }, 'steps to seek to an arbitrary earlier time (mean)'),
    svgEl('text', { x: 14, y: (T + H - B) / 2, class: 'cmp-axis', 'text-anchor': 'middle', transform: `rotate(-90 14 ${(T + H - B) / 2})` }, 'memory held after the run'),
  );

  // the checkpoint intervals are one design at three settings: join them
  const ck = plotted.filter((p) => p.strategy === 'checkpoint');
  if (ck.length > 1) svg.append(svgEl('polyline', { points: ck.map((p) => `${lx(p.seekMean).toFixed(1)},${ly(p.bytes).toFixed(1)}`).join(' '), class: 'cmp-line', stroke: COLOUR.checkpoint, 'stroke-dasharray': '4 4', 'stroke-width': 1.5 }));
  for (const p of plotted) {
    const x = lx(p.seekMean), y = ly(p.bytes);
    svg.append(svgEl('circle', { cx: x, cy: y, r: p.strategy === 'reversible' ? 6 : 5, fill: COLOUR[p.strategy] }));
    const [dx, dy, anchor] = p.strategy === 'checkpoint' ? [10, 4, 'start' as const] : LABEL[p.strategy];
    const label = p.strategy === 'checkpoint' ? `every ${n0(Number(p.name.replace(/\D/g, '')))}` : p.name;
    svg.append(svgEl('text', { x: x + dx, y: y + dy, class: 'cmp-end', fill: COLOUR[p.strategy], 'text-anchor': anchor }, `${label}  ${formatBytes(p.bytes)}`));
  }
  const key = plotted.find((p) => p.strategy === 'checkpoint');
  if (key) svg.append(svgEl('text', { x: lx(key.seekMean) + 10, y: ly(key.bytes) - 12, class: 'cmp-axis', fill: COLOUR.checkpoint }, 'Checkpoint and replay'));
  return svg;
}

/**
 * "Benchmarks": the fair baselines from bench/results.json, drawn. Memory held against how far back you want to seek, for the
 * naive diary (our logging VM, labelled naive), the tight diary, checkpoint-and-replay and the reversible program. Pong and
 * sort are measured against conventional twins that take fewer steps, so the numbers are lined up by frame (Pong) or by run.
 */
export function benchSection(): HTMLElement {
  const el = h('section', 'cmp-section bench');
  const head = h('div', 'cmp-head');
  const pick = h('div', 'segmented');
  pick.setAttribute('role', 'group');
  pick.setAttribute('aria-label', 'benchmark program');
  head.append(h('h3', 'cmp-h', 'Benchmarks: memory held against steps to undo'), pick);
  const sub = h('p', 'dim cmp-sub', 'Measured offline on the real engines and their conventional twins, not live. Both axes use a log scale.');
  const chart = h('div', 'cmp-chart');
  const table = h('div', 'cmp-table');
  const note = h('p', 'cmp-verdict');
  el.append(head, sub, chart, table, note);

  const draw = (which: 'pong' | 'sort'): void => {
    buttons.forEach(({ id, b }) => b.setAttribute('aria-pressed', String(id === which)));
    table.replaceChildren();
    const header = h('div', 'trow thead brow');
    ['Strategy', 'Memory held', 'Back one step', 'Seek (mean)'].forEach((t) => header.append(h('span', '', t)));
    table.append(header);
    const row = (name: string, cells: string[], bold = false): void => {
      const tr = h('div', `trow brow${bold ? ' brow-strong' : ''}`);
      tr.append(h('span', 'tlabel', name));
      cells.forEach((c) => tr.append(h('span', 'tcell mono', c)));
      table.append(tr);
    };
    if (which === 'pong') {
      const r = results.pong;
      const pts = pongPoints(r);
      chart.replaceChildren(benchChart(pts));
      for (const p of pts) row(p.name, [formatBytes(p.bytes), p.back1, `${n0(p.seekMean ?? 0)} steps`], p.strategy === 'reversible');
      note.textContent =
        `${r.frames} frames of Pong. The reversible program keeps ${formatBytes(r.reversibleGarbageBytes)} (its key log) and its machine keeps ${formatBytes(r.reversibleMachineHistoryBytes)}. ` +
        `It runs ${(r.reversibleStepsPerFrame / r.conventionalStepsPerFrame).toFixed(1)} times as many instructions as the conventional twin (${r.reversibleStepsPerFrame.toFixed(0)} against ${r.conventionalStepsPerFrame.toFixed(0)} a frame), ` +
        'and the twin cannot run in step with it, so the two are compared by frame. The naive diary is our logging engine at 48 bytes a step; the tight diary and the checkpoints are the fairer rivals. ' +
        'Checkpointing is the strongest: a snapshot every 10,000 steps uses about as much memory and seeks much faster, but going back one step can mean replaying thousands.';
    } else {
      const r = results.sort;
      chart.replaceChildren();
      row('Naive diary', [formatBytes(r.naiveDiaryBytes), '1 undo step', 'not measured']);
      row('Tight diary', [formatBytes(r.tightDiaryBytes), '1 undo step', 'not measured']);
      row('Reversible', [`${r.garbageFlagsSet} of ${r.garbageFlagsPossible} garbage flags`, '1 inverse step', 'not measured'], true);
      note.textContent =
        `Sorting 8 numbers. The reversible sort keeps ${formatBytes(r.reversibleMachineHistoryBytes)} in the machine and up to ${r.garbageFlagsPossible} bits of garbage (${r.garbageFlagsSet} set). ` +
        `It runs ${(r.reversibleSteps / r.conventionalSteps).toFixed(1)} times as many instructions as the conventional twin (${r.reversibleSteps} against ${r.conventionalSteps}). Seeking and checkpoints were not measured for sort, so there is no chart.`;
    }
  };
  const buttons = (['pong', 'sort'] as const).map((id) => {
    const b = h('button', 'seg', id === 'pong' ? 'Pong' : 'Sort');
    b.type = 'button';
    b.addEventListener('click', () => draw(id));
    pick.append(b);
    return { id, b };
  });
  draw('pong');
  return el;
}
